const synthetics = require('Synthetics');
const log = require('SyntheticsLogger');

// Runs on a fixed schedule regardless of real customer traffic (Section 3.2:
// "This works even when no customers are browsing"). Two steps stand in for
// the "scripted browse and checkout journey": load the storefront home page,
// then load the checkout page, failing the canary run if either does not
// return a healthy status.

const checkPage = async function (stepName, path) {
  const page = await synthetics.getPage();
  const url = `${process.env.TARGET_URL}${path}`;

  const response = await page.goto(url, {
    waitUntil: 'domcontentloaded',
    timeout: 30000,
  });

  if (!response) {
    throw new Error(`${stepName}: no response received from ${url}`);
  }

  const status = response.status();
  if (status < 200 || status >= 400) {
    throw new Error(`${stepName}: ${url} returned HTTP ${status}`);
  }

  log.info(`${stepName}: ${url} returned HTTP ${status}`);
};

const storefrontJourney = async function () {
  await synthetics.executeStep('loadHomePage', () => checkPage('loadHomePage', '/'));
  await synthetics.executeStep('loadCheckoutPage', () => checkPage('loadCheckoutPage', '/checkout'));
};

exports.handler = async () => {
  return await storefrontJourney();
};
